steps.body:
A **promise** stands for a value that arrives later. Wrap timer-based work in `new Promise`, and call `resolve(value)` when it succeeds or `reject(error)` when it fails:

```javascript
function delay(value, ms) {
  return new Promise((resolve) => {
    setTimeout(() => resolve(value), ms);
  });
}

function failAfter(message, ms) {
  return new Promise((_, reject) => {
    setTimeout(() => reject(new Error(message)), ms);
  });
}
delay("done", 10).then((value) => console.log(value)); // done
```

`failAfter("offline", 10).catch((error) => console.log(error.message))` prints `offline`. A `reject` and a `throw` inside `then` land in the same `catch`.

- `promise.then((value) => ...)` returns a new promise, so calls chain. Each `then` receives what the one before it returned, so always `return` (a missing `return` passes `undefined`).
- Throwing inside a `then` skips every remaining `then` and jumps to the next `catch`.
- `promise.catch((error) => ...)` handles the rejection.
- `promise.finally(() => ...)` runs either way, which suits cleanup. It receives no value.

`Promise.resolve(value)` and `Promise.reject(error)` make a promise that is already settled. Even then, `then` callbacks never run right away: they wait for the current synchronous code to finish, and they run before any timer callback. A rejection that nothing catches crashes Node, so end every chain with `catch`.

example.code:
const input = require("fs").readFileSync(0, "utf8");
const numbers = input.trim().split(/\s+/).map(Number);

function delay(value, ms) {
  return new Promise((resolve) => {
    setTimeout(() => resolve(value), ms);
  });
}

for (const [i, n] of numbers.entries()) {
  delay(n, 20 * (i + 1))
    .then((value) => {
      if (value % 2 !== 0) {
        throw new Error(`${value} is odd`);
      }
      return value;
    })
    .then((value) => value * 2)
    .then((value) => value + 1)
    .then((result) => console.log(`result: ${result}`))
    .catch((error) => console.log(`error: ${error.message}`))
    .finally(() => console.log("cleanup"));
}
console.log("chains started");

