steps.body:
An `async` function always returns a promise. Its `return` value resolves that promise, and a `throw` inside it rejects it. Inside, `await promise` pauses the function until the promise settles, then gives back its value or throws its error, so plain `try`/`catch` handles rejections. CommonJS has no top-level `await`: put the code in `async function main()` and call `main();`.

```javascript
const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));
sleep(20).then(() => console.log("20 ms later")); // 20 ms later
```

Gotcha 1: inside `try`, write `return await work()`. A bare `return work()` hands back the promise before it settles, so its rejection skips your local `catch` and lands on the caller.

Gotcha 2: `forEach` does not wait for async callbacks.

```javascript harness
const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));
{{code}}
```

```javascript
[30, 10, 20].forEach(async (ms) => {
  await sleep(ms);
  console.log(`waited ${ms}`);
});
console.log("finished");
```

This prints `finished` first, then `waited 10`, `waited 20`, and `waited 30`. To run tasks one after another, put `await` inside a `for...of` loop.

example.code:
const input = require("fs").readFileSync(0, "utf8");
const steps = input.trim().split("\n").map((line) => {
  const [name, msText] = line.trim().split(/\s+/);
  return { name, ms: Number(msText) };
});

const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

async function runStep(name, ms) {
  if (ms > 100) {
    throw new Error("too slow");
  }
  await sleep(ms);
  return `${name} done`;
}

async function safeStep(name, ms) {
  try {
    return await runStep(name, ms);
  } catch (error) {
    return `${name} skipped (${error.message})`;
  }
}

async function main() {
  for (const { name, ms } of steps) {
    console.log(await safeStep(name, ms));
  }
  console.log("all steps finished");
}

main();

