const input = require("fs").readFileSync(0, "utf8");
const tasks = input.trim().split("\n").map((line) => {
  const [name, msText] = line.trim().split(/\s+/);
  return { name, ms: Number(msText) };
});

const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

async function runTask(name, ms) {
  await sleep(ms);
  if (name === "fail") {
    throw new Error("task failed");
  }
  return `${name} ok`;
}

async function safeTask(name, ms) {
  try {
    return await runTask(name, ms);
  } catch (error) {
    return `${name} error (${error.message})`;
  }
}

async function main() {
  for (const { name, ms } of tasks) {
    console.log(await safeTask(name, ms));
  }
  console.log("all tasks finished");
}

main();

steps.body:
Awaiting tasks one by one adds up their times. To run them in parallel, start every promise first, then await them. Here `sleep(ms)` is `new Promise((resolve) => setTimeout(resolve, ms))`, a promise that resolves after `ms` milliseconds:

```javascript harness
const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

async function main() {
  const startedAt = Date.now();
  {{code}}
  console.log(`both done after about ${Date.now() - startedAt} ms`);
}

main();
```

```javascript
// inside an async function
const first = sleep(30);
const second = sleep(20);
await first;
await second; // about 30 ms in total, not 50
```

`Promise.all` is the usual way to do this. Pair it with `map` and an async callback: `await Promise.all(items.map(async (item) => ...))`. It resolves to an array of results in **input order**, not finishing order. It rejects as soon as one promise rejects, with that error. The other tasks keep running, but their results are lost.

- `Promise.allSettled(promises)` never rejects. It waits for every promise and reports each one as `{ status: "fulfilled", value }` or `{ status: "rejected", reason }`.
- `Promise.race(promises)` settles like the first promise to settle, whether it resolved or rejected, so wrap it in `try`/`catch` as well.

Gotcha: with promises started by hand, one that rejects before you reach its `await` crashes Node. `Promise.all` and its relatives watch every promise at once, so prefer them.

example.code:
const input = require("fs").readFileSync(0, "utf8");
const services = input.trim().split("\n").map((line) => {
  const [name, msText, state] = line.trim().split(/\s+/);
  return { name, ms: Number(msText), up: state === "up" };
});

const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

async function check({ name, ms, up }) {
  await sleep(ms);
  if (!up) {
    throw new Error(`${name} timed out`);
  }
  return name;
}

async function main() {
  const results = await Promise.allSettled(services.map((service) => check(service)));
  for (const [i, result] of results.entries()) {
    const { name, ms } = services[i];
    if (result.status === "fulfilled") {
      console.log(`${name}: up (${ms} ms)`);
    } else {
      console.log(`${name}: down (${result.reason.message})`);
    }
  }

  try {
    const names = await Promise.all(services.map((service) => check(service)));
    console.log(`all: ok (${names.join(", ")})`);
  } catch (error) {
    console.log(`all: failed (${error.message})`);
  }

  try {
    const fastest = await Promise.race(services.map((service) => check(service)));
    console.log(`first: ${fastest}`);
  } catch (error) {
    console.log(`first: failed (${error.message})`);
  }
}

main();

